const input = $input.first().json;
const body = input.body || {};

const minStock = body.payload?.minStock || 0;
const currentStock = body.payload?.currentStock || 0;
const suggestedQty = Math.ceil(Math.max(0, (minStock - currentStock) * 1.2));

return [{ json: {
  received: true,
  eventId: body.eventId,
  type: body.type,
  tenantId: body.tenantId,
  source: body.source,
  correlationId: body.correlationId,
  productName: body.payload?.productName,
  productId: body.payload?.productId,
  currentStock,
  minStock,
  suggestedQty,
  timestamp: new Date().toISOString()
}}];
